 order(S, 'Расположите по возрастанию.', ['$2^{30}$', '$3^{20}$', '$5^{15}$', '$10^{12}$'], '$2^{30} \\approx 1{,}07 \\cdot 10^9 < 3^{20} \\approx 3{,}5 \\cdot 10^9 < 5^{15} \\approx 3{,}05 \\cdot 10^{10} < 10^{12}$.'),
 num(S, 'Найдите значение $\\dfrac{x^{7} \\cdot x^{3}}{x^{8}}$ при $x = {{x}}$.', 'x^2', '', 'Упростим: $x^2$.', [C('x', [-3, 4, 11, 15])]),
